async function downloadWorkbook(sheets: Record<string, unknown[]>, fileName: string) {
  const XLSX = await loadXlsx();
  const workbook = XLSX.utils.book_new();
  Object.entries(sheets).forEach(([name, rows]) => XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(rows.length ? rows : [{ Note: "Not provided" }]), name.slice(0, 31)));
  XLSX.writeFile(workbook, fileName);
}

async function downloadStyledDailyWorkbook(data: any, date: string) {
  const XLSX = await loadXlsx();
  const projects = (data?.projects ?? []).filter((project: any) => project.status === "ACTIVE");
  const testers = (data?.testers ?? []).filter((tester: any) => tester.status === "ACTIVE");
  const leaders = new Map<number, string>((data?.leaders ?? []).map((leader: any) => [leader.leaderId, leader.leader] as [number, string]));
  const performance = data?.performance ?? [];
  const matrix: Array<Array<string | number>> = [["Project", ...projects.map((project: any) => project.name), "Total"]];
  const headerStyle = { fill: { fgColor: { rgb: "D9E1F2" } }, font: { bold: true, color: { rgb: "000000" } }, alignment: { horizontal: "center" } };
  const leaderStyle = { fill: { fgColor: { rgb: "D9EAD3" } }, font: { bold: true, color: { rgb: "000000" } } };
  const totalStyle = { fill: { fgColor: { rgb: "B4C6E7" } }, font: { bold: true, color: { rgb: "0F172A" } } };
  const groups = new Map<string, any[]>();
  for (const tester of testers) { const leader = leaders.get(tester.teamLeaderId) ?? "Unassigned"; const group = groups.get(leader) ?? []; group.push(tester); groups.set(leader, group); }
  groups.forEach((group, leader) => {
    const values = projects.map((project: any) => group.reduce((sum: number, tester: any) => sum + performance.filter((row: any) => row.testerId === tester.id && row.projectId === project.id).reduce((n: number, row: any) => n + Number(row.quantity), 0), 0));
    matrix.push([leader, ...values, values.reduce((sum: number, value: number) => sum + value, 0)]);
    for (const tester of group) { const testerValues = projects.map((project: any) => performance.filter((row: any) => row.testerId === tester.id && row.projectId === project.id).reduce((n: number, row: any) => n + Number(row.quantity), 0)); matrix.push([tester.name, ...testerValues, testerValues.reduce((sum: number, value: number) => sum + value, 0)]); }
  });
  matrix.push(["Grand Total", ...projects.map((project: any) => performance.filter((row: any) => row.projectId === project.id).reduce((n: number, row: any) => n + Number(row.quantity), 0)), performance.reduce((n: number, row: any) => n + Number(row.quantity), 0)]);
  const sheet = XLSX.utils.aoa_to_sheet(matrix); sheet["!cols"] = [{ wch: 24 }, ...projects.map(() => ({ wch: 14 })), { wch: 14 }];
  for (let column = 0; column < matrix[0]!.length; column++) { const cell = sheet[XLSX.utils.encode_cell({ r: 0, c: column })] as any; if (cell) cell.s = headerStyle; }
  let rowIndex = 1; groups.forEach(group => { const cell = sheet[XLSX.utils.encode_cell({ r: rowIndex, c: 0 })] as any; if (cell) cell.s = leaderStyle; for (let column = 1; column < matrix[0]!.length; column++) { const subtotal = sheet[XLSX.utils.encode_cell({ r: rowIndex, c: column })] as any; if (subtotal) subtotal.s = leaderStyle; } rowIndex += group.length + 1; });
  for (let column = 0; column < matrix[0]!.length; column++) { const cell = sheet[XLSX.utils.encode_cell({ r: matrix.length - 1, c: column })] as any; if (cell) cell.s = totalStyle; }
  const workbook = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(workbook, sheet, "Daily Report"); XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(performance.map((row: any) => ({ Date: date, Tester: testers.find((tester: any) => tester.id === row.testerId)?.name ?? "Unknown", "Team Leader": leaders.get(row.teamLeaderId) ?? "Unassigned", Project: projects.find((project: any) => project.id === row.projectId)?.name ?? "Unknown", Quantity: Number(row.quantity) }))), "Raw Data"); XLSX.writeFile(workbook, `Daily_Operations_Report_${date}.xlsx`, { cellStyles: true });
  toast.success("Styled daily report downloaded");
}

type AssistantReportRow = { leader: string; tester: string; superX: number; sectionX: number; total: number; superXPayout?: number; sectionXPayout?: number; totalPayout?: number };
type AssistantReport = { date: string; stored: number; exceptions: string[]; rows: AssistantReportRow[]; payoutRequested?: boolean };

function reportMatrix(rows: AssistantReportRow[]) {
  const leaderNames = Array.from(new Set(rows.map(row => row.leader)));
  const matrix: Array<Array<string | number>> = [["Project", "Section X", "Super x", "Total"]];
  for (const leader of leaderNames) {
    const group = rows.filter(row => row.leader === leader);
    matrix.push([leader, group.reduce((sum, row) => sum + row.sectionX, 0), group.reduce((sum, row) => sum + row.superX, 0), group.reduce((sum, row) => sum + row.total, 0)]);
    for (const row of group) matrix.push([row.tester, row.sectionX, row.superX, row.total]);
  }
  matrix.push(["Grand Total", rows.reduce((sum, row) => sum + row.sectionX, 0), rows.reduce((sum, row) => sum + row.superX, 0), rows.reduce((sum, row) => sum + row.total, 0)]);
  return matrix;
}

async function downloadAssistantWorkbook(report: AssistantReport) {
  const XLSX = await loadXlsx();
  const workbook = XLSX.utils.book_new();
  const payoutMode = Boolean(report.payoutRequested);
  const groups = Array.from(new Set(report.rows.map(row => row.leader))).map(leader => ({ leader, rows: report.rows.filter(row => row.leader === leader) }));
  const matrix = payoutMode ? [["Team Leader / Tester", "Role", "Section X OTP", "Section X Payout", "Super X OTP", "Super X Payout", "Total OTP", "Total Payout", "Status"], ...groups.flatMap(group => { const subtotal = group.rows.reduce((a, row) => ({ sectionX: a.sectionX + row.sectionX, sectionXPay: a.sectionXPay + (row.sectionXPayout ?? 0), superX: a.superX + row.superX, superXPay: a.superXPay + (row.superXPayout ?? 0), total: a.total + row.total, totalPay: a.totalPay + (row.totalPayout ?? 0) }), { sectionX: 0, sectionXPay: 0, superX: 0, superXPay: 0, total: 0, totalPay: 0 }); return [[group.leader, "Team Leader", subtotal.sectionX, subtotal.sectionXPay, subtotal.superX, subtotal.superXPay, subtotal.total, subtotal.totalPay, "Team Subtotal"], ...group.rows.map(row => [row.tester, "Tester", row.sectionX, row.sectionXPayout ?? 0, row.superX, row.superXPayout ?? 0, row.total, row.totalPayout ?? 0, "Active"])] }), ["GRAND TOTAL", "Category Summary", report.rows.reduce((s, r) => s + r.sectionX, 0), report.rows.reduce((s, r) => s + (r.sectionXPayout ?? 0), 0), report.rows.reduce((s, r) => s + r.superX, 0), report.rows.reduce((s, r) => s + (r.superXPayout ?? 0), 0), report.rows.reduce((s, r) => s + r.total, 0), report.rows.reduce((s, r) => s + (r.totalPayout ?? 0), 0), "Overall"]] : reportMatrix(report.rows);
  const sheet = XLSX.utils.aoa_to_sheet(matrix);
  sheet["!cols"] = payoutMode ? [{ wch: 24 }, { wch: 18 }, { wch: 14 }, { wch: 18 }, { wch: 14 }, { wch: 18 }, { wch: 14 }, { wch: 18 }, { wch: 18 }] : [{ wch: 24 }, { wch: 14 }, { wch: 16 }, { wch: 14 }];
  XLSX.utils.book_append_sheet(workbook, sheet, "Formatted Report");
  XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(groups.map(group => ({ "Team Leader": group.leader, "Section X OTP": group.rows.reduce((s, r) => s + r.sectionX, 0), "Section X Payout": group.rows.reduce((s, r) => s + (r.sectionXPayout ?? 0), 0), "Super X OTP": group.rows.reduce((s, r) => s + r.superX, 0), "Super X Payout": group.rows.reduce((s, r) => s + (r.superXPayout ?? 0), 0), "Total OTP": group.rows.reduce((s, r) => s + r.total, 0), "Total Payout": group.rows.reduce((s, r) => s + (r.totalPayout ?? 0), 0) }))), "Team Leaders");
  XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(report.rows.map(row => ({ "Team Leader": row.leader, Tester: row.tester, "Section X OTP": row.sectionX, "Section X Payout": row.sectionXPayout ?? 0, "Super X OTP": row.superX, "Super X Payout": row.superXPayout ?? 0, "Total OTP": row.total, "Total Payout": row.totalPayout ?? 0 }))), "Testers");
  XLSX.writeFile(workbook, `AI_Report_${report.date}.xlsx`);
}

function downloadAssistantImage(report: AssistantReport) {
  const canvas = document.createElement("canvas"); const scale = 2; const rowHeight = 38; const headerHeight = 54; canvas.width = 900 * scale; canvas.height = (headerHeight + (report.rows.length + new Set(report.rows.map(row => row.leader)).size + 2) * rowHeight) * scale; const context = canvas.getContext("2d"); if (!context) return; context.scale(scale, scale); context.fillStyle = "#ffffff"; context.fillRect(0, 0, 900, canvas.height / scale); const cols = [0, 430, 585, 745, 900]; context.fillStyle = "#d9e7f3"; context.fillRect(0, 0, 900, headerHeight); context.fillStyle = "#0f172a"; context.font = "700 24px Arial"; context.fillText("Project", 10, 36); context.fillText("Super x", 445, 36); context.fillText("Section X", 595, 36); context.fillText("Total", 780, 36); let y = headerHeight; const leaderNames = Array.from(new Set(report.rows.map(row => row.leader))); for (const leader of leaderNames) { const group = report.rows.filter(row => row.leader === leader); const totals = { superX: group.reduce((sum, row) => sum + row.superX, 0), sectionX: group.reduce((sum, row) => sum + row.sectionX, 0), total: group.reduce((sum, row) => sum + row.total, 0) }; context.fillStyle = "#c9e2b4"; context.fillRect(0, y, 900, rowHeight); context.fillStyle = "#111827"; context.font = "700 22px Arial"; context.fillText(leader, 10, y + 26); context.textAlign = "right"; context.fillText(String(totals.superX), cols[2] - 12, y + 26); context.fillText(String(totals.sectionX), cols[3] - 12, y + 26); context.fillText(String(totals.total), cols[4] - 12, y + 26); context.textAlign = "left"; y += rowHeight; for (const row of group) { context.fillStyle = "#ffffff"; context.fillRect(0, y, 900, rowHeight); context.strokeStyle = "#e2e8f0"; context.beginPath(); context.moveTo(0, y + rowHeight - 1); context.lineTo(900, y + rowHeight - 1); context.stroke(); context.fillStyle = "#111827"; context.font = "400 20px Arial"; context.fillText(row.tester, 10, y + 25); context.textAlign = "right"; context.fillText(String(row.superX), cols[2] - 12, y + 25); context.fillText(String(row.sectionX), cols[3] - 12, y + 25); context.font = "700 20px Arial"; context.fillText(String(row.total), cols[4] - 12, y + 25); context.textAlign = "left"; y += rowHeight; } } const grand = { superX: report.rows.reduce((sum, row) => sum + row.superX, 0), sectionX: report.rows.reduce((sum, row) => sum + row.sectionX, 0), total: report.rows.reduce((sum, row) => sum + row.total, 0) }; context.fillStyle = "#b9cdea"; context.fillRect(0, y, 900, rowHeight); context.fillStyle = "#111827"; context.font = "700 22px Arial"; context.fillText("Grand Total", 10, y + 26); context.textAlign = "right"; context.fillText(String(grand.superX), cols[2] - 12, y + 26); context.fillText(String(grand.sectionX), cols[3] - 12, y + 26); context.fillText(String(grand.total), cols[4] - 12, y + 26); const link = document.createElement("a"); link.download = `AI_Report_${report.date}.png`; link.href = canvas.toDataURL("image/png"); link.click();
}

